const raw = String($json.body?.domain || $json.body?.email || '').trim().toLowerCase();
let domain = raw.includes('@') && !raw.includes('://') ? raw.split('@').pop() : raw;
domain = domain.replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
if (!domain || !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(domain)) {
  throw new Error('Invalid public domain input');
}
const blocked = ['localhost', '127.0.0.1', '169.254.169.254'];
if (blocked.includes(domain) || domain.endsWith('.local') || domain.endsWith('.internal')) {
  throw new Error('Blocked non-public domain');
}
return [{ json: { domain, callGoal: String($json.body?.callGoal || 'Discovery call prep').slice(0, 240), notes: String($json.body?.notes || '').slice(0, 600) } }];

const base = $('Normalize Domain & Safety Gate').first().json;
const homeHtml = String($('Fetch Company Homepage').first()?.json?.data || '');
const pricingHtml = String($('Probe Pricing Page').first()?.json?.data || '');
const newsXml = String($('Fetch Google News RSS').first()?.json?.data || '');
const combined = (homeHtml + '\n' + pricingHtml).toLowerCase();
const stack = [];
if (/cdn\.shopify\.com/.test(combined)) stack.push('Shopify');
if (/hs-scripts\.com|hubspot/.test(combined)) stack.push('HubSpot');
if (/intercom/.test(combined)) stack.push('Intercom');
if (/stripe\.com/.test(combined)) stack.push('Stripe');
if (/calendly\.com/.test(combined)) stack.push('Calendly');
if (/next\/static/.test(combined)) stack.push('Next.js');
const hasPricing = pricingHtml.length > 200 || /pricing|per month/.test(combined);
const hasHiring = /careers|open roles|we.?re hiring/.test(combined);
const hasNews = /<item>/.test(newsXml);
const score = 20 + (hasPricing ? 20 : 6) + (hasHiring ? 20 : 5) + (stack.length ? 18 : 20) + (hasNews ? 18 : 6);
const strip = (s) => s.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1400);
return [{ json: { domain: base.domain, callGoal: base.callGoal, notes: base.notes, stack, hasPricing, hasHiring, hasNews, score: Math.min(100, score), excerpt: strip(homeHtml) } }];

const scored = $('Deterministic Stack & Signal Scorer').first().json;
let brief = {};
try { brief = JSON.parse($json.choices?.[0]?.message?.content || '{}'); } catch { brief = {}; }
const slackText = `*Pre-Call Brief: ${scored.domain}* (Signal Score: ${scored.score}/100)\n• Stack: ${scored.stack.join(', ') || 'None detected'}\n• Pricing detected: ${scored.hasPricing} | Hiring signals: ${scored.hasHiring}\n• Opener: ${brief.openingLine || 'See full brief in CRM log.'}`;
return [{ json: { ...scored, brief, slackText } }];
